    // 获取游戏当前日期
    function getGameDate() {
        const currentDateStr = '{{xbgetvar::世界.当前状态.日期}}';

        // 如果宏没有被替换，使用当前系统日期
        if (currentDateStr.includes('{{xbgetvar::')) {
            const now = new Date();
            return {
                year: now.getFullYear(),
                month: now.getMonth(),
                day: now.getDate()
            };
        }

        // 解析日期字符串 (格式: YYYY-MM-DD)
        const dateParts = currentDateStr.split('-');
        if (dateParts.length === 3) {
            return {
                year: parseInt(dateParts[0], 10),
                month: parseInt(dateParts[1], 10) - 1, // 月份从0开始
                day: parseInt(dateParts[2], 10)
            };
        }

        // 如果解析失败，使用当前系统日期
        const now = new Date();
        return {
            year: now.getFullYear(),
            month: now.getMonth(),
            day: now.getDate()
        };
    }

    // 获取亲密记录 - 爱心显示的核心逻辑
    // 爱心显示条件：日期存在于林若兰的亲密日历中
    // 触发方式：每次射精时自动将当前日期添加到亲密日历
    function getIntimacyRecords() {
        const intimacyRecordsStr = '{{xbgetvar::世界.林若兰.亲密日历}}';

        console.log('=== 爱心显示调试信息 ===');
        console.log('原始亲密记录字符串:', intimacyRecordsStr);

        // 如果宏没有被替换，尝试从其他途径获取或返回空数组
        if (intimacyRecordsStr.includes('{{xbgetvar::')) {
            console.warn('亲密日历变量未被正确替换，使用空数组');
            return [];
        }

        try {
            let records = [];

            // 处理可能的数组格式或字符串格式
            if (intimacyRecordsStr.trim().startsWith('[')) {
                records = JSON.parse(intimacyRecordsStr);
            } 
            // 如果是逗号分隔的字符串格式
            else if (intimacyRecordsStr.includes(',')) {
                records = intimacyRecordsStr.split(',').map(s => s.trim()).filter(s => s);
            }
            // 如果是单个日期
            else if (intimacyRecordsStr.trim().length > 0) {
                records = [intimacyRecordsStr.trim()];
            }

            console.log('解析后的亲密记录:', records);
            console.log('=== 爱心显示调试结束 ===');
            return records;
        } catch(e) {
            console.error('解析亲密记录失败:', e, '原始字符串:', intimacyRecordsStr);
            return [];
        }
    }

    // 检查偷看美女视频次数的变量状态
    function checkBeautyVideosCount() {
        const beautyCountElement = document.getElementById('beauty-videos-count');
        const beautyCountValue = beautyCountElement.textContent;

        // 如果宏没有被替换，显示警告
        if (beautyCountValue.includes('{{xbgetvar::')) {
            beautyCountElement.textContent = '0';
            beautyCountElement.classList.add('value-warning');
            console.warn('偷看美女视频次数变量可能不存在或路径错误:', beautyCountValue);
        } else {
            beautyCountElement.classList.remove('value-warning');
        }
