                console.log(`❤ 为日期 ${currentDateStr} 显示爱心标记`);
            }

            // 检查是否是游戏当前日期
            if (todayInfo.day === day && todayInfo.month === month && todayInfo.year === year) {
                todayMarkerHTML = '<div class="today-marker"></div>';
            }

            calendarHTML += `<div class="calendar-day">${day}${checkmarkHTML}${todayMarkerHTML}</div>`;
        }

        // 补齐剩余空白单元格
        const totalCells = firstDayOfMonth + daysInMonth;
        const remainingCells = (7 - (totalCells % 7)) % 7;
        for (let i = 0; i < remainingCells; i++) {
            calendarHTML += '<div class="calendar-day empty"></div>';
        }

        document.getElementById('calendar-grid').innerHTML = calendarHTML;
    }

    // 切换区域展开/收起
    function toggleSection(header) {
