        // 默认展开第一个区域
        const firstHeader = document.querySelector('.section-header');
        if(firstHeader) {
            toggleSection(firstHeader);
        }

        // 添加爱心显示调试
        debugLoveHearts();

        // 定期检查变量更新（每5秒）
        setInterval(checkBeautyVideosCount, 5000);

        // 定期检查爱心显示状态（每10秒）
